/**
 *  Default styles for xterm.js
 */

.xterm {
    cursor: text;
    position: relative;
    user-select: none;
    -ms-user-select: none;
    -webkit-user-select: none;
}

.xterm.focus,
.xterm:focus {
    outline: none;
}

.xterm .xterm-helpers {
    position: absolute;
    top: 0;
    /**
     * The z-index of the helpers must be higher than the canvases in order for
     * IMEs to appear on top.
     */
    z-index: 5;
}

.xterm .xterm-helper-textarea {
    padding: 0;
    border: 0;
    margin: 0;
    /* Move textarea out of the screen to the far left, so that the cursor is not visible */
    position: absolute;
    opacity: 0;
    left: -9999em;
    top: 0;
    width: 0;
    height: 0;
    z-index: -5;
    /** Prevent wrapping so the IME appears against the textarea at the correct position */
    white-space: nowrap;
    overflow: hidden;
    resize: none;
}

.xterm .composition-view {
    /* TODO: Composition position got messed up somewhere */
    background: #000;
    color: #FFF;
    display: none;
    position: absolute;
    white-space: nowrap;
    z-index: 1;
}

.xterm .composition-view.active {
    display: block;
}

.xterm .xterm-viewport {
    /* On OS X this is required in order for the scroll bar to appear fully opaque */
    background-color: #000;
    overflow-y: scroll;
    cursor: default;
    position: absolute;
    right: 0;
    left: 0;
    top: 0;
    bottom: 0;
}

.xterm .xterm-screen {
    position: relative;
}

.xterm .xterm-screen canvas {
    position: absolute;
    left: 0;
    top: 0;
}

.xterm .xterm-scroll-area {
    visibility: hidden;
}

.xterm-char-measure-element {
    display: inline-block;
    visibility: hidden;
    position: absolute;
    top: 0;
    left: -9999em;
    line-height: normal;
}

.xterm.enable-mouse-events {
    /* When mouse events are enabled (eg. tmux), revert to the standard pointer cursor */
    cursor: default;
}

.xterm.xterm-cursor-pointer,
.xterm .xterm-cursor-pointer {
    cursor: pointer;
}

.xterm.column-select.focus {
    /* Column selection mode */
    cursor: crosshair;
}

.xterm .xterm-accessibility:not(.debug),
.xterm .xterm-message {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    right: 0;
    z-index: 10;
    color: transparent;
    pointer-events: none;
}

.xterm .xterm-accessibility-tree:not(.debug) *::selection {
  color: transparent;
}

.xterm .xterm-accessibility-tree {
  user-select: text;
  white-space: pre;
}

.xterm .live-region {
    position: absolute;
    left: -9999px;
    width: 1px;
    height: 1px;
    overflow: hidden;
}

.xterm-dim {
    /* Dim should not apply to background, so the opacity of the foreground color is applied
     * explicitly in the generated class and reset to 1 here */
    opacity: 1 !important;
}

.xterm-underline-1 { text-decoration: underline; }
.xterm-underline-2 { text-decoration: double underline; }
.xterm-underline-3 { text-decoration: wavy underline; }
.xterm-underline-4 { text-decoration: dotted underline; }
.xterm-underline-5 { text-decoration: dashed underline; }

.xterm-overline {
    text-decoration: overline;
}

.xterm-overline.xterm-underline-1 { text-decoration: overline underline; }
.xterm-overline.xterm-underline-2 { text-decoration: overline double underline; }
.xterm-overline.xterm-underline-3 { text-decoration: overline wavy underline; }
.xterm-overline.xterm-underline-4 { text-decoration: overline dotted underline; }
.xterm-overline.xterm-underline-5 { text-decoration: overline dashed underline; }

.xterm-strikethrough {
    text-decoration: line-through;
}

.xterm-screen .xterm-decoration-container .xterm-decoration {
	z-index: 6;
	position: absolute;
}

.xterm-screen .xterm-decoration-container .xterm-decoration.xterm-decoration-top-layer {
	z-index: 7;
}

.xterm-decoration-overview-ruler {
    z-index: 8;
    position: absolute;
    top: 0;
    right: 0;
    pointer-events: none;
}

.xterm-decoration-top {
    z-index: 2;
    position: relative;
}

/* terminal-desk 面板布局样式（td- 前缀防泄漏；slot 作用域注入）
   色值一律取主题 CSS 变量（--c-*），与宿主主题体系同源；禁硬编码色值 */

.td-root {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: rgb(var(--c-bg-base));
  color: rgb(var(--c-text-primary));
  font-size: 13px;
}

/* ── tab 栏 ─────────────────────────────────────────────── */
.td-tabbar {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 4px 6px;
  border-bottom: 1px solid rgb(var(--c-border));
  background: rgb(var(--c-bg-subtle));
  overflow-x: auto;
  flex: none;
  scrollbar-width: thin;
}
.td-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: rgb(var(--c-text-secondary));
  cursor: pointer;
  white-space: nowrap;
  max-width: 220px;
  font-size: 12px;
}
.td-tab:hover { background: rgb(var(--c-bg-hover)); }
.td-tab-on {
  background: rgb(var(--c-bg-active));
  border-color: rgb(var(--c-border));
  color: rgb(var(--c-text-primary));
}
.td-tab-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.td-tab-input {
  width: 110px;
  padding: 1px 4px;
  border: 1px solid rgb(var(--c-primary));
  border-radius: 4px;
  background: rgb(var(--c-bg-base));
  color: rgb(var(--c-text-primary));
  font-size: 12px;
  outline: none;
}
.td-tab-close {
  border: 0;
  background: transparent;
  color: rgb(var(--c-text-secondary));
  cursor: pointer;
  border-radius: 4px;
  padding: 0 2px;
  line-height: 1;
  font-size: 12px;
}
.td-tab-close:hover { color: rgb(var(--c-danger, var(--c-text-primary))); background: rgb(var(--c-bg-hover)); }
.td-tab-exit {
  font-size: 10px;
  padding: 0 4px;
  border-radius: 8px;
  background: rgb(var(--c-bg-hover));
  color: rgb(var(--c-text-secondary));
}
.td-tabbar-actions {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin-left: auto;
  flex: none;
}
.td-iconbtn {
  border: 0;
  background: transparent;
  color: rgb(var(--c-text-secondary));
  cursor: pointer;
  border-radius: 6px;
  padding: 3px 7px;
  font-size: 13px;
  line-height: 1;
}
.td-iconbtn:hover { background: rgb(var(--c-bg-hover)); color: rgb(var(--c-text-primary)); }

/* ── 会话区 ─────────────────────────────────────────────── */
.td-stage {
  flex: 1;
  min-height: 0;
  position: relative;
  display: flex;
  flex-direction: column;
}
.td-session {
  flex: 1;
  min-height: 0;
  min-width: 0;
  padding: 2px 4px 4px 8px;
}
.td-session-hidden { display: none; }
.td-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: rgb(var(--c-text-secondary));
}
.td-exitbanner {
  flex: none;
  padding: 6px 10px;
  font-size: 12px;
  background: rgb(var(--c-bg-subtle));
  border-bottom: 1px solid rgb(var(--c-border));
  color: rgb(var(--c-text-secondary));
  display: flex;
  align-items: center;
  gap: 10px;
}
.td-errorbar {
  flex: none;
  padding: 6px 10px;
  font-size: 12px;
  color: rgb(var(--c-danger, #f87171));
  background: rgb(var(--c-bg-subtle));
  border-bottom: 1px solid rgb(var(--c-border));
}

/* ── 脚本抽屉 ───────────────────────────────────────────── */
.td-drawer {
  flex: none;
  height: 256px;
  display: flex;
  flex-direction: column;
  border-top: 1px solid rgb(var(--c-border));
  background: rgb(var(--c-bg-subtle));
}
.td-drawer-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border-bottom: 1px solid rgb(var(--c-border));
  flex: none;
}
.td-drawer-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 6px 8px;
  scrollbar-width: thin;
}
.td-script {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border-radius: 6px;
  cursor: pointer;
}
.td-script:hover { background: rgb(var(--c-bg-hover)); }
.td-script-name {
  flex: none;
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
}
.td-script-cmd {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: Consolas, Menlo, 'Courier New', monospace;
  font-size: 11px;
  color: rgb(var(--c-text-secondary));
}
.td-script-actions {
  display: inline-flex;
  gap: 4px;
  flex: none;
  opacity: 0;
}
.td-script:hover .td-script-actions { opacity: 1; }
.td-mini {
  border: 1px solid rgb(var(--c-border));
  border-radius: 5px;
  background: rgb(var(--c-bg-base));
  color: rgb(var(--c-text-secondary));
  cursor: pointer;
  font-size: 11px;
  padding: 2px 7px;
}
.td-mini:hover { color: rgb(var(--c-text-primary)); border-color: rgb(var(--c-primary)); }
.td-input {
  padding: 4px 8px;
  border: 1px solid rgb(var(--c-border));
  border-radius: 6px;
  background: rgb(var(--c-bg-base));
  color: rgb(var(--c-text-primary));
  outline: none;
  font-size: 12px;
  min-width: 0;
}
.td-input:focus { border-color: rgb(var(--c-primary)); }
.td-chip {
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 11px;
  background: rgb(var(--c-bg-hover));
  color: rgb(var(--c-text-secondary));
  cursor: pointer;
  border: 1px solid transparent;
}
.td-chip-on {
  background: rgb(var(--c-bg-active));
  color: rgb(var(--c-text-primary));
  border-color: rgb(var(--c-border));
}
.td-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex: none;
}
.td-status-running { background: rgb(var(--c-success, #34d399)); }
.td-status-failed { background: rgb(var(--c-danger, #f87171)); }
.td-status-stopped { background: rgb(var(--c-text-secondary)); }

/* ── 运行命令浮层 ───────────────────────────────────────── */
.td-modal-mask {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 48px;
  z-index: 30;
}
.td-modal {
  width: min(560px, calc(100% - 32px));
  background: rgb(var(--c-bg-base));
  border: 1px solid rgb(var(--c-border));
  border-radius: 10px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}
.td-modal-input {
  width: 100%;
  box-sizing: border-box;
  padding: 12px 14px;
  border: 0;
  border-bottom: 1px solid rgb(var(--c-border));
  background: transparent;
  color: rgb(var(--c-text-primary));
  outline: none;
  font-family: Consolas, Menlo, 'Courier New', monospace;
  font-size: 13px;
}
.td-modal-list {
  max-height: 260px;
  overflow-y: auto;
  padding: 4px;
}
.td-modal-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
}
.td-modal-item-on { background: rgb(var(--c-bg-active)); }
.td-modal-hint {
  padding: 6px 12px;
  border-top: 1px solid rgb(var(--c-border));
  color: rgb(var(--c-text-secondary));
  font-size: 11px;
  display: flex;
  gap: 14px;
}
